"""Native category-bounded runs with explicit original endpoint ownership.

Runs reuse the certified source path and direct-quad profile construction. Their
private endpoint declarations never become junctions or free-end aliases.
"""
import bpy
from . import curved_junction_nodes as boundary, curved_standalone_nodes
from .curved_network_ownership_nodes import _compare
c=boundary.c
MAX_RUNS=1024


def endpoint_valid(g,sources,spans,rows,at,span,side,end,sid,*,selection_cuts=False,interior_cuts=False):
    read=lambda key:c._read(g,spans,'st_ps_'+key,span,'INT')
    row=lambda key:c._read(g,rows,'st_br_'+side+'_'+key,at,'INT')
    role,owner,peer=[row(k) for k in ('role','owner','next_section')]
    first,last,count,start=[read(k) for k in ('first','last','count','edge_start')]
    knot=first if end==0 else last
    outer=0 if end==0 else count-1.
    free=_compare(g,role,1)*_compare(g,owner,-1)*_compare(g,peer,-1)*_compare(g,knot,outer)
    near=start+(first if end==0 else last-1.)
    far=start+(first-1. if end==0 else last)
    edge=lambda key,index:boundary._edge_sample(g,sources,c.named(g,key,'INT'),index,'INT')
    local=_compare(g,role,4)*_compare(g,owner,sid)*_compare(g,peer,edge('st_section_id',far))
    local=local*_compare(g,edge('st_street_id',far),sid)*(1.-_compare(g,peer,edge('st_section_id',near)))
    local=local*_compare(g,far,start,'GREATER_EQUAL')*_compare(g,far,start+count-1.,'LESS_THAN')
    local=local*(1.-_compare(g,edge('_ps_feature_group',near),edge('_ps_feature_group',far)))
    from .curved_category_handoff_nodes import valid as cross_valid
    cross=cross_valid(g,sources,spans,span,1-end,role,owner,peer,sid)
    selection=0.
    if selection_cuts:
        from .curved_selection_boundary_nodes import endpoint
        _,selection=endpoint(g,spans,span,side,role,owner,peer,interior_cuts=interior_cuts,sources=sources)
    present=1.
    for key in ('role','owner','next_section'):
        attr=g.node('GeometryNodeInputNamedAttribute');attr.data_type='INT'
        attr.inputs['Name'].default_value='st_br_'+side+'_'+key
        present=present*c._stat(g,rows,attr.outputs['Exists'])
    proof=g.node('GeometryNodeInputNamedAttribute');proof.data_type='INT'
    proof.inputs['Name'].default_value='st_ps_'+side+'_role'
    present=present*c._stat(g,spans,proof.outputs['Exists'])
    return present*_compare(g,role,read(side+'_role'))*g.math('MINIMUM',1.,free+local+cross+selection)


def extend(core, *, interpolation=False):
    name='Prochitecture Streets / Category-bounded run assembly v1'
    if interpolation:name+=' / Exact or smooth v1'
    if name in bpy.data.node_groups:return bpy.data.node_groups[name]
    g=c.Graph(name)
    sockets=[s for s in core.interface.items_tree if s.item_type=='SOCKET']
    for s in sockets:g.socket(s.name,s.socket_type,s.in_out,default=getattr(s,'default_value',None))
    g.socket('Boundary Runs','NodeSocketGeometry');g.socket('Boundary Run Count','NodeSocketInt',default=0)
    inp=g.node('NodeGroupInput');out=g.node('NodeGroupOutput')
    base=g.node('GeometryNodeGroup','Preserve existing connected and standalone construction');base.node_tree=core
    for s in sockets:
        if s.in_out=='INPUT':g.bind(inp.outputs[s.name],base.inputs[s.name])
    rows=inp.outputs['Boundary Runs'];mapping=inp.outputs['Mapping'];count=c._count(g,rows)
    budget=_compare(g,count,inp.outputs['Boundary Run Count'])*_compare(g,count,MAX_RUNS,'LESS_EQUAL')
    ri=g.node('GeometryNodeRepeatInput','Once-owned declared category-bounded runs')
    ro=g.node('GeometryNodeRepeatOutput');ro.repeat_items.clear()
    for kind,key in (('GEOMETRY','Geometry'),('GEOMETRY','Failures'),('BOOLEAN','Valid')):ro.repeat_items.new(kind,key)
    ri.pair_with_output(ro);ri.inputs['Valid'].default_value=True
    g.bind(c.choose(g,budget,count,0,'INT'),ri.inputs['Iterations']);at=c.V(g,ri.outputs['Iteration'])
    call=g.node('GeometryNodeGroup','Shared original-span profile and quad construction')
    call.node_tree=curved_standalone_nodes.street(boundary_span=True,interpolation=interpolation)
    for key in ('Sources','Mapping','Boundary Runs','Cell Size','Height Exaggeration'):g.bind(inp.outputs[key],call.inputs[key])
    g.bind(at,call.inputs['Index'])
    span=c._read(g,rows,'st_br_span',at,'INT');sid=c._read(g,rows,'st_br_street_id',at,'INT')
    unique=1.
    for name,prefix in (('Approaches','st_pp_span'),('Corridors','st_cs_span_index'),
                        ('External Approaches','st_ca_span_index'),('Standalone Streets','st_fs_span')):
        unique=unique*_compare(g,c._stat(g,inp.outputs[name],_compare(g,c.named(g,prefix,'INT'),span),'Sum'),0)
    peer=c.named(g,'st_br_span','INT')
    own_first=c._read(g,mapping,'st_ps_first',span,'INT');own_last=c._read(g,mapping,'st_ps_last',span,'INT')
    other_first=c._read(g,mapping,'st_ps_first',peer,'INT');other_last=c._read(g,mapping,'st_ps_last',peer,'INT')
    overlap=_compare(g,c.named(g,'st_br_street_id','INT'),sid)*_compare(g,own_first,other_last,'LESS_THAN')*_compare(g,other_first,own_last,'LESS_THAN')
    unique=unique*_compare(g,c._stat(g,rows,overlap,'Sum'),1)
    valid=c.V(g,call.outputs['Valid'])*unique
    mesh=c._store(g,call.outputs['Geometry'],'st_cn_height',c.named(g,'st_cs_height'))
    from .curved_network_surface_nodes import _tag
    mesh=_tag(g,mesh,at,6)
    g.bind(boundary._join(g,ri.outputs['Geometry'],boundary._empty(g,mesh,valid)),ro.inputs['Geometry'])
    pos=c._sample(g,inp.outputs['Sources'],g.position(),
        c._read(g,mapping,'st_ps_start',span,'INT')+own_first,'FLOAT_VECTOR')
    failure=g.setpos(c._line(g,1),pos)
    code=c.choose(g,unique,c.choose(g,call.outputs['Inputs Valid'],c.choose(g,call.outputs['Cells Valid'],6,5,'INT'),1,'INT'),32,'INT')
    section=c._read(g,mapping,'st_ps_first_section',span,'INT')
    for key,value in (('st_diagnostic_code',code),('st_section_id',section),('st_street_id',sid),
                      ('st_intersection_id',-1),('st_bundle_id',-1),('st_cn_kind',6),('st_cn_owner',at)):
        failure=c._store(g,failure,key,value,'INT')
    g.bind(boundary._join(g,ri.outputs['Failures'],boundary._empty(g,failure,1.-valid)),ro.inputs['Failures'])
    g.bind(c.V(g,ri.outputs['Valid'])*valid,ro.inputs['Valid'])
    has_base=g.math('GREATER_THAN',c._count(g,inp.outputs['Junctions'])+c._count(g,inp.outputs['Standalone Streets']),.5)
    empty_ok=1.
    for key in ('Approaches','Corridors','External Approaches','Compounds','Logical Clusters','Separators'):
        empty_ok=empty_ok*_compare(g,c._count(g,inp.outputs[key]),0)
    registry=budget*c.choose(g,has_base,1.,empty_ok)*g.math('MAXIMUM',has_base,g.math('GREATER_THAN',count,.5))
    mesh=boundary._join(g,boundary._empty(g,base.outputs['Geometry'],has_base),ro.outputs['Geometry'])
    failures=boundary._join(g,boundary._empty(g,base.outputs['Failure Records'],has_base),ro.outputs['Failures'])
    error=c._line(g,1)
    for key,value in (('st_diagnostic_code',32),('st_section_id',-1),('st_intersection_id',-1),
                      ('st_bundle_id',-1),('st_cn_kind',-1),('st_cn_owner',-1)):
        error=c._store(g,error,key,value,'INT')
    sizes=g.node('GeometryNodeAttributeDomainSize');sizes.component='MESH';g.bind(mesh,sizes.inputs['Geometry'])
    for s in sockets:
        if s.in_out!='OUTPUT':continue
        value=base.outputs[s.name]
        if s.name=='Geometry':value=boundary._empty(g,mesh,registry)
        elif s.name=='Failure Records':value=c.choose(g,registry,failures,error,'GEOMETRY')
        elif s.name=='Valid':value=registry*c.choose(g,has_base,base.outputs['Valid'],1.)*c.V(g,ro.outputs['Valid'])
        elif s.name=='Output Valid':value=registry*g.math('GREATER_THAN',sizes.outputs['Face Count'],.5)
        g.bind(value,out.inputs[s.name])
